#!/usr/bin/env bash
# 首次生成 env/.env（chmod 600）；已存在则不动，避免覆盖本地密码。
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"
ENV_FILE="${ROOT}/env/.env"

if [[ -f "${ENV_FILE}" ]]; then
    echo "env/.env already exists; leaving it unchanged"
    exit 0
fi

rand_hex() { openssl rand -hex 16; }
rand_b64() { openssl rand -base64 32 | tr -d '\n'; }

mkdir -p "${ROOT}/env"
umask 077
cat > "${ENV_FILE}" <<EOF
# generated by scripts/gen-secrets.sh; do not commit
ENTRY_HTTP_PORT=80
TZ=Asia/Shanghai

PG_SUPERUSER_PASSWORD=$(rand_hex)
MYSQL_ROOT_PASSWORD=$(rand_hex)
MYSQL_REPL_PASSWORD=$(rand_hex)
MONGO_ROOT_PASSWORD=$(rand_hex)
REDIS_PASSWORD=$(rand_hex)
RABBITMQ_PASSWORD=$(rand_hex)
RABBITMQ_ERLANG_COOKIE=$(rand_hex)
GRAFANA_ADMIN_PASSWORD=$(rand_hex)
NACOS_TOKEN_SECRET_KEY=$(rand_b64)
EOF
chmod 600 "${ENV_FILE}"
echo "wrote env/.env (chmod 600); use 'make secrets-show' to print"
